  1→/**
  2→ * run-unity-pipeline.ts — Unity 多态三段管线串联入口（WT-044）
  3→ *
  4→ * 串起三段（DR-44）：
  5→ *   1. explore LLM  (explore-service.ts --source unity) → findings.json + verdict.json
  6→ *   2. narrative LLM (narrative-service.ts --source unity) → narrative.json
  7→ *                  （detectStateMode 检测 base/cur 子目录 → 选 unity-multi-state.txt 模板）
  8→ *   3. render 纯代码 (render-html.ts --dir <output>) → report.html
  9→ *
 10→ * Usage (from repo root or web/):
 11→ *   npx tsx web/server/prism/run-unity-pipeline.ts --multi-state-dir <udiff_dir> [--out <dir>] [--skip-explore]
 12→ *
 13→ * --multi-state-dir: udiff 目录路径（含 base/ + cur/ 子目录，每个有 preprocess-result.json）
 14→ * --out: 输出目录（默认 web/data/prism-out/<udiff_id>/<timestamp>）
 15→ * --skip-explore: 跳过 explore 阶段（复用已有 findings.json/verdict.json），只跑 narrative + render。
 16→ *                 用于反复调 narrative/render 不重跑 explore。
 17→ *
 18→ * 注意：本脚本会实际调用 LLM（explore + narrative），耗时较长（explore ~10-20min, narrative ~5min）。
 19→ */
 20→
 21→import { runPrismExplore } from './explore-service.js';
 22→import { runPrismNarrative } from './narrative-service.js';
 23→import { registerBuiltinPipelines } from './report-pipeline.js';
 24→import { spawn } from 'node:child_process';
 25→import * as path from 'node:path';
 26→import * as fs from 'node:fs';
 27→import { fileURLToPath } from 'node:url';
 28→
 29→// ESM 兼容：__dirname 在 ESM 下未定义
 30→const __filename = fileURLToPath(import.meta.url);
 31→const __dirname = path.dirname(__filename);
 32→
 33→// ──────────────────────────────── CLI 参数 ────────────────────────────────
 34→
 35→const argv = process.argv.slice(2);
 36→function getFlag(flag: string): string | undefined {
 37→  const idx = argv.indexOf(flag);
 38→  return idx === -1 ? undefined : argv[idx + 1];
 39→}
 40→function hasFlag(flag: string): boolean {
 41→  return argv.includes(flag);
 42→}
 43→
 44→if (hasFlag('--help') || hasFlag('-h')) {
 45→  console.log(
 46→    'Usage: npx tsx web/server/prism/run-unity-pipeline.ts --multi-state-dir <udiff_dir> [--out <dir>] [--skip-explore] [--timeout-ms <ms>]\n' +
 47→    '\n' +
 48→    '  --multi-state-dir  udiff 目录路径（含 base/ + cur/ 子目录）\n' +
 49→    '  --out              Output directory (default: web/data/prism-out/<udiff_id>/<timestamp>)\n' +
 50→    '  --skip-explore     Skip explore stage (reuse existing findings.json/verdict.json)\n' +
 51→    '  --timeout-ms       Per-stage timeout in ms (default: 1200000 = 20 min for explore, 600000 = 10 min for narrative)\n',
 52→  );
 53→  process.exit(0);
 54→}
 55→
 56→const multiStateDirArg = getFlag('--multi-state-dir');
 57→const rawOutDir = getFlag('--out');
 58→const skipExplore = hasFlag('--skip-explore');
 59→const timeoutMs = getFlag('--timeout-ms') ? parseInt(getFlag('--timeout-ms')!, 10) : undefined;
 60→
 61→if (!multiStateDirArg && !skipExplore) {
 62→  console.error('[pipeline] --multi-state-dir is required (or use --skip-explore with --run-id)');
 63→  process.exit(1);
 64→}
 65→
 66→// 解析 udiff 目录：相对路径相对于 cwd（通常 web/），绝对路径直接用
 67→const multiStateDir = multiStateDirArg
 68→  ? (path.isAbsolute(multiStateDirArg) ? multiStateDirArg : path.resolve(process.cwd(), multiStateDirArg))
 69→  : undefined;
 70→
 71→// runId = udiff 目录名（如 udiff_1782983710451_be175ef1）
 72→const runId = multiStateDir ? path.basename(multiStateDir) : (getFlag('--run-id') ?? 'udiff_1782983710451_be175ef1');
 73→
 74→// WT-031 需求 C：--out 相对于 cwd 解析
 75→const outputDir = rawOutDir
 76→  ? (path.isAbsolute(rawOutDir) ? rawOutDir : path.resolve(process.cwd(), rawOutDir))
 77→  : undefined;
 78→
 79→// ──────────────────────────────── 主流程 ────────────────────────────────
 80→
 81→async function main(): Promise<void> {
 82→  // 注册内置 pipeline（unity + perfetto）
 83→  registerBuiltinPipelines();
 84→  console.log('[pipeline] Registered builtin pipelines: unity, perfetto');
 85→
 86→  const repoRoot = path.resolve(__dirname, '../../..');
 87→  let exploreOutputDir: string;  // explore 阶段的输出目录（findings.json/verdict.json 所在）
 88→  let narrativeOutputDir: string;  // narrative + render 阶段的输出目录（narrative.json/report.html 所在）
 89→
 90→  // ── 阶段 1：explore LLM ──
 91→  if (skipExplore) {
 92→    // 复用已有 findings.json/verdict.json：找最新的 run 目录
 93→    const runBaseDir = path.join(repoRoot, 'web', 'data', 'prism-out', runId);
 94→    if (!fs.existsSync(runBaseDir)) {
 95→      console.error(`[pipeline] --skip-explore but run dir not found: ${runBaseDir}`);
 96→      process.exit(1);
 97→    }
 98→    // 找含 findings.json 的最新时间戳子目录
 99→    const subdirs = fs.readdirSync(runBaseDir)
100→      .filter(d => fs.statSync(path.join(runBaseDir, d)).isDirectory())
101→      .filter(d => fs.existsSync(path.join(runBaseDir, d, 'findings.json')))
102→      .sort()
103→      .reverse();
104→    exploreOutputDir = subdirs.length > 0
105→      ? path.join(runBaseDir, subdirs[0])
106→      : runBaseDir;
107→    if (!fs.existsSync(path.join(exploreOutputDir, 'findings.json'))) {
108→      console.error(`[pipeline] --skip-explore but findings.json not found in: ${exploreOutputDir}`);
109→      process.exit(1);
110→    }
111→    console.log(`[pipeline] Stage 1 (explore): SKIPPED, reusing ${exploreOutputDir}`);
112→
113→    // --skip-explore 模式下支持 --out 新目录，不覆盖原报告
114→    if (outputDir) {
115→      narrativeOutputDir = path.isAbsolute(outputDir) ? outputDir : path.resolve(process.cwd(), outputDir);
116→      if (!fs.existsSync(narrativeOutputDir)) {
117→        fs.mkdirSync(narrativeOutputDir, { recursive: true });
118→        console.log(`[pipeline] Created new output dir: ${narrativeOutputDir}`);
119→      }
120→      // 复制 findings.json + verdict.json 到新目录（narrative-service 要读 findings.json）
121→      for (const fname of ['findings.json', 'verdict.json']) {
122→        const src = path.join(exploreOutputDir, fname);
123→        const dst = path.join(narrativeOutputDir, fname);
124→        if (fs.existsSync(src) && !fs.existsSync(dst)) {
125→          fs.copyFileSync(src, dst);
126→          console.log(`[pipeline] Copied ${fname} → ${narrativeOutputDir}`);
127→        }
128→      }
129→      console.log(`[pipeline] --skip-explore + --out: narrative/render will write to ${narrativeOutputDir} (original ${exploreOutputDir} untouched)`);
130→    } else {
131→      console.warn(`[pipeline] WARNING: --skip-explore without --out will overwrite existing narrative.json/report.html in ${exploreOutputDir}`);
132→      console.warn(`[pipeline] Suggestion: add --out data/prism-out/${runId}/<new-timestamp> to preserve original`);
133→      narrativeOutputDir = exploreOutputDir;
134→    }
135→  } else {
136→    console.log('[pipeline] Stage 1 (explore): starting...');
137→    const exploreResult = await runPrismExplore({
138→      source: 'unity',
139→      runId,
140→      outputDir,
141→      timeoutMs: timeoutMs ?? 20 * 60 * 1000,
142→    });
143→    if (!exploreResult.success) {
144→      console.error(`[pipeline] Stage 1 (explore) FAILED: ${exploreResult.error}`);
145→      process.exit(1);
146→    }
147→    exploreOutputDir = path.dirname(exploreResult.findingsPath);
148→    narrativeOutputDir = outputDir ? (path.isAbsolute(outputDir) ? outputDir : path.resolve(process.cwd(), outputDir)) : exploreOutputDir;
149→    console.log(`[pipeline] Stage 1 (explore): OK, ${exploreResult.findings.length} findings → ${exploreOutputDir}`);
150→  }
151→
152→  // ── 阶段 2：narrative LLM ──
153→  console.log('[pipeline] Stage 2 (narrative): starting...');
154→  const narrativeResult = await runPrismNarrative({
155→    source: 'unity',
156→    runId,
157→    outputDir: narrativeOutputDir,
158→    timeoutMs: timeoutMs ?? 10 * 60 * 1000,
159→  });
160→  if (!narrativeResult.success) {
161→    console.error(`[pipeline] Stage 2 (narrative) FAILED: ${narrativeResult.error}`);
162→    process.exit(1);
163→  }
164→  console.log(`[pipeline] Stage 2 (narrative): OK → ${narrativeResult.narrativePath}`);
165→
166→  // ── 阶段 3：render 纯代码 ──
167→  console.log('[pipeline] Stage 3 (render): starting...');
168→  const renderScript = path.join(__dirname, 'render-html.ts');
169→  const renderArgs = ['--import', 'tsx', renderScript, '--dir', narrativeOutputDir];
170→  const renderExitCode = await new Promise<number>((resolve) => {
171→    const child = spawn('node', renderArgs, {
172→      cwd: path.join(repoRoot, 'web'),
173→      stdio: 'inherit',
174→      shell: false,
175→    });
176→    child.on('close', resolve);
177→    child.on('error', (err) => {
178→      console.error(`[pipeline] Stage 3 (render) spawn error: ${err.message}`);
179→      resolve(1);
180→    });
181→  });
182→  if (renderExitCode !== 0) {
183→    console.error(`[pipeline] Stage 3 (render) FAILED: exit code ${renderExitCode}`);
184→    process.exit(1);
185→  }
186→  const reportHtmlPath = path.join(narrativeOutputDir, 'report.html');
187→  console.log(`[pipeline] Stage 3 (render): OK → ${reportHtmlPath}`);
188→
189→  console.log('\n════════════════════════════════════════');
190→  console.log('  Unity 多态三段管线 — 完成');
191→  console.log('════════════════════════════════════════');
192→  console.log(`  findings.json  : ${path.join(narrativeOutputDir, 'findings.json')}`);
193→  console.log(`  narrative.json : ${narrativeResult.narrativePath}`);
194→  console.log(`  report.html    : ${reportHtmlPath}`);
195→  console.log('════════════════════════════════════════');
196→}
197→
198→main().catch((err) => {
199→  console.error('[pipeline] Unexpected error:', err instanceof Error ? err.message : String(err));
200→  process.exit(1);
201→});
202→

  1→import path from 'path';
  2→import fs from 'fs';
  3→import { eq } from 'drizzle-orm';
  4→import { getDb } from '../db/index.js';
  5→import { sessions } from '../db/schema.js';
  6→import { getConfig } from '../utils/config.js';
  7→import { executeCli, type AnalysisJob } from './cli-executor.js';
  8→import { extractMetrics } from './metrics-extractor.js';
  9→import { assetService } from './asset-service.js';
 10→import { emitProgress } from '../routes/analysis.js';
 11→import type { CliProvider } from '../../shared/types.js';
 12→
 13→export interface AnalysisParams {
 14→  targetFps?: number;
 15→  jankMultiplier?: number;
 16→  bigJankMultiplier?: number;
 17→  budgetRatio?: number;
 18→}
 19→
 20→interface QueueItem {
 21→  sessionId: string;
 22→  cliProvider: CliProvider;
 23→  params?: AnalysisParams;
 24→  addedAt: number;
 25→}
 26→
 27→interface QueueStatus {
 28→  running: string | null;
 29→  queued: QueueItem[];
 30→  totalProcessed: number;
 31→}
 32→
 33→class AnalysisQueue {
 34→  private queue: QueueItem[] = [];
 35→  private running: string | null = null;
 36→  private totalProcessed = 0;
 37→
 38→  /** 将分析任务加入队列，返回队列位置 */
 39→  enqueue(sessionId: string, cliProvider: CliProvider = 'codebuddy', params?: AnalysisParams): number {
 40→    this.queue.push({ sessionId, cliProvider, params, addedAt: Date.now() });
 41→    const position = this.queue.length;
 42→
 43→    // 如果没有正在运行的任务，立即开始处理
 44→    if (!this.running) {
 45→      this.processNext();
 46→    }
 47→
 48→    return position;
 49→  }
 50→
 51→  /** 获取队列状态 */
 52→  getStatus(): QueueStatus {
 53→    return {
 54→      running: this.running,
 55→      queued: [...this.queue],
 56→      totalProcessed: this.totalProcessed,
 57→    };
 58→  }
 59→
 60→  /** 获取某个任务在队列中的位置（0 表示正在运行，-1 表示不在队列中） */
 61→  getPosition(sessionId: string): number {
 62→    if (this.running === sessionId) return 0;
 63→    const idx = this.queue.findIndex(q => q.sessionId === sessionId);
 64→    return idx === -1 ? -1 : idx + 1;
 65→  }
 66→
 67→  /** 处理下一个任务 */
 68→  private async processNext(): Promise<void> {
 69→    if (this.running || this.queue.length === 0) return;
 70→
 71→    const item = this.queue.shift()!;
 72→    this.running = item.sessionId;
 73→
 74→    try {
 75→      await this.executeJob(item.sessionId, item.cliProvider, item.params);
 76→    } catch (err: any) {
 77→      console.error(`Analysis failed for ${item.sessionId}:`, err);
 78→    } finally {
 79→      this.running = null;
 80→      this.totalProcessed++;
 81→      // 继续处理下一个
 82→      this.processNext();
 83→    }
 84→  }
 85→
 86→  /** 执行单个分析任务 */
 87→  private async executeJob(sessionId: string, cliProvider: CliProvider, params?: AnalysisParams): Promise<void> {
 88→    const config = getConfig();
 89→    const db = getDb();
 90→
 91→    // 获取 session 信息
 92→    const session = await db.select().from(sessions).where(eq(sessions.id, sessionId)).get();
 93→    if (!session || !session.filePath) {
 94→      await db.update(sessions).set({
 95→        status: 'failed',
 96→        error: '会话不存在或文件路径为空',
 97→        completedAt: Date.now(),
 98→      }).where(eq(sessions.id, sessionId));
 99→      emitProgress({
100→        sessionId,
101→        stage: 'failed',
102→        progress: 0,
103→        message: '会话不存在或文件路径为空',
104→        timestamp: Date.now(),
105→      });
106→      return;
107→    }
108→
109→    // 更新状态为 running
110→    const startTime = Date.now();
111→    await db.update(sessions).set({ status: 'running' }).where(eq(sessions.id, sessionId));
112→
113→    emitProgress({
114→      sessionId,
115→      stage: 'preprocessing',
116→      progress: 5,
117→      message: '开始分析...',
118→      timestamp: Date.now(),
119→    });
120→
121→    // 准备输出目录
122→    const outputDir = path.join(config.dataDir, 'results', sessionId);
123→
124→    // 执行 CLI 分析
125→    const job: AnalysisJob = {
126→      sessionId,
127→      skill: 'unity_profiler',
128→      inputPath: session.filePath,
129→      pdataPath: session.filePath,
130→      outputDir,
131→      cliProvider,
132→      params,
133→    };
134→
135→    const result = await executeCli(job);
136→
137→    const endTime = Date.now();
138→    const duration = endTime - startTime;
139→
140→    // 保存日志到文件（无论成功失败都保存）
141→    if (result.logs && result.logs.length > 0) {
142→      try {
143→        fs.mkdirSync(outputDir, { recursive: true });
144→        fs.writeFileSync(
145→          path.join(outputDir, 'analysis.log'),
146→          result.logs.join('\n'),
147→          'utf-8',
148→        );
149→        console.log(`[Queue] Logs saved to ${path.join(outputDir, 'analysis.log')} (${result.logs.length} lines)`);
150→      } catch (err: any) {
151→        console.warn(`[Queue] Failed to save logs: ${err.message}`);
152→      }
153→    }
154→
155→    if (result.success) {
156→      // 提取指标存入数据库
157→      try {
158→        await extractMetrics(sessionId, outputDir);
159→        await registerGeneratedAssets(sessionId, outputDir);
160→
161→        // 全部成功 → completed
162→        await db.update(sessions).set({
163→          status: 'completed',
164→          completedAt: endTime,
165→          duration,
166→        }).where(eq(sessions.id, sessionId));
167→
168→        emitProgress({
169→          sessionId,
170→          stage: 'completed',
171→          progress: 100,
172→          message: '分析完成，报告已保存',
173→          timestamp: Date.now(),
174→          log: '[完成] 指标和报告已写入数据库',
175→        });
176→      } catch (err: any) {
177→        // extractMetrics 失败 → 标记为 failed
178→        const errMsg = `数据提取失败: ${err.message}`;
179→        console.error(`[Queue] ${errMsg}`);
180→
181→        await db.update(sessions).set({
182→          status: 'failed',
183→          error: errMsg.slice(0, 1000),
184→          completedAt: endTime,
185→          duration,
186→        }).where(eq(sessions.id, sessionId));
187→
188→        emitProgress({
189→          sessionId,
190→          stage: 'failed',
191→          progress: 0,
192→          message: errMsg,
193→          timestamp: Date.now(),
194→          log: `[错误] ${errMsg}`,
195→        });
196→      }
197→    } else {
198→      await db.update(sessions).set({
199→        status: 'failed',
200→        error: result.error?.slice(0, 1000),
201→        completedAt: endTime,
202→        duration,
203→      }).where(eq(sessions.id, sessionId));
204→
205→      emitProgress({
206→        sessionId,
207→        stage: 'failed',
208→        progress: 0,
209→        message: result.error || '分析失败',
210→        timestamp: Date.now(),
211→        log: `[错误] ${result.error || '未知错误'}`,
212→      });
213→    }
214→  }
215→}
216→
217→async function registerGeneratedAssets(sessionId: string, outputDir: string) {
218→  const generatedFiles = [
219→    {
220→      fileName: 'preprocess-result.json',
221→      filePath: path.join(outputDir, 'preprocess-result.json'),
222→      assetType: 'report_json',
223→      role: 'output',
224→      mimeType: 'application/json',
225→    },
226→    {
227→      fileName: 'performance-report.md',
228→      filePath: path.join(outputDir, 'performance-report.md'),
229→      assetType: 'report_md',
230→      role: 'report',
231→      mimeType: 'text/markdown',
232→    },
233→  ];
234→
235→  for (const item of generatedFiles) {
236→    if (!fs.existsSync(item.filePath)) continue;
237→    const asset = await assetService.registerExistingFile({
238→      filePath: item.filePath,
239→      fileName: item.fileName,
240→      assetType: item.assetType,
241→      source: 'generated',
242→      mimeType: item.mimeType,
243→      metadata: { sessionId, outputDir },
244→    });
245→    await assetService.linkSessionAsset({
246→      sessionId,
247→      sessionType: 'profiler',
248→      assetId: asset.id,
249→      role: item.role,
250→    });
251→  }
252→}
253→
254→/** 全局单例队列 */
255→export const analysisQueue = new AnalysisQueue();
256→

  1→/**
  2→ * run-perfetto-pipeline.ts — Perfetto 三段管线串联入口（DR-44 WT-027 B4）
  3→ *
  4→ * 串起三段：
  5→ *   1. explore LLM  (explore-service.ts --source perfetto) → findings.json + verdict.json
  6→ *   2. narrative LLM (narrative-service.ts --source perfetto) → narrative.json
  7→ *   3. render 纯代码 (render-html.ts --dir <output>) → report.html
  8→ *
  9→ * Usage (from repo root):
 10→ *   npx tsx web/server/prism/run-perfetto-pipeline.ts [--run-id <id>] [--out <dir>] [--skip-explore]
 11→ *
 12→ * --skip-explore: 跳过 explore 阶段（复用已有 findings.json/verdict.json），只跑 narrative + render。
 13→ *                 用于 WT-028 反复调 narrative/render 不重跑 explore。
 14→ *
 15→ * 注意：本脚本会实际调用 LLM（explore + narrative），耗时较长（explore ~10-20min, narrative ~5min）。
 16→ * 纯 dry-run（不调 LLM）请用 --help 查看用法，或单独跑类型检查。
 17→ */
 18→
 19→import { runPrismExplore } from './explore-service.js';
 20→import { runPrismNarrative } from './narrative-service.js';
 21→import { registerBuiltinPipelines } from './report-pipeline.js';
 22→import { spawn } from 'node:child_process';
 23→import * as path from 'node:path';
 24→import * as fs from 'node:fs';
 25→import { fileURLToPath } from 'node:url';
 26→
 27→// ESM 兼容：__dirname 在 ESM 下未定义
 28→const __filename = fileURLToPath(import.meta.url);
 29→const __dirname = path.dirname(__filename);
 30→
 31→// ──────────────────────────────── CLI 参数 ────────────────────────────────
 32→
 33→const argv = process.argv.slice(2);
 34→function getFlag(flag: string): string | undefined {
 35→  const idx = argv.indexOf(flag);
 36→  return idx === -1 ? undefined : argv[idx + 1];
 37→}
 38→function hasFlag(flag: string): boolean {
 39→  return argv.includes(flag);
 40→}
 41→
 42→if (hasFlag('--help') || hasFlag('-h')) {
 43→  console.log(
 44→    'Usage: npx tsx web/server/prism/run-perfetto-pipeline.ts [--run-id <id>] [--out <dir>] [--skip-explore] [--timeout-ms <ms>]\n' +
 45→    '\n' +
 46→    '  --run-id      Run ID (default: bk26b-perfetto-triad)\n' +
 47→    '  --out         Output directory (default: web/data/prism-out/<runId>/<timestamp>)\n' +
 48→    '  --skip-explore  Skip explore stage (reuse existing findings.json/verdict.json)\n' +
 49→    '  --timeout-ms  Per-stage timeout in ms (default: 1200000 = 20 min for explore, 600000 = 10 min for narrative)\n',
 50→  );
 51→  process.exit(0);
 52→}
 53→
 54→const runId = getFlag('--run-id') ?? 'bk26b-perfetto-triad';
 55→const rawOutDir = getFlag('--out');
 56→const skipExplore = hasFlag('--skip-explore');
 57→const timeoutMs = getFlag('--timeout-ms') ? parseInt(getFlag('--timeout-ms')!, 10) : undefined;
 58→
 59→// WT-031 需求 C：--out 相对于 cwd 解析（用户通常在 web/ 下跑，--out data/prism-out/... → web/data/prism-out/...）
 60→// 这样 narrative-service 和 render-html 都能正确找到 perfetto triad 数据（在 runBase/cur/ 下）
 61→// 绝对路径原样用，相对路径相对于 cwd（不是 repoRoot，避免 explore-service 的 path.resolve(repoRoot) 误解析）
 62→const outputDir = rawOutDir
 63→  ? (path.isAbsolute(rawOutDir) ? rawOutDir : path.resolve(process.cwd(), rawOutDir))
 64→  : undefined;
 65→
 66→// ──────────────────────────────── 主流程 ────────────────────────────────
 67→
 68→async function main(): Promise<void> {
 69→  // 注册内置 pipeline（unity + perfetto）
 70→  registerBuiltinPipelines();
 71→  console.log('[pipeline] Registered builtin pipelines: unity, perfetto');
 72→
 73→  const repoRoot = path.resolve(__dirname, '../../..');
 74→  let exploreOutputDir: string;  // explore 阶段的输出目录（findings.json/verdict.json 所在）
 75→  let narrativeOutputDir: string;  // narrative + render 阶段的输出目录（narrative.json/report.html 所在）
 76→
 77→  // ── 阶段 1：explore LLM ──
 78→  if (skipExplore) {
 79→    // 复用已有 findings.json/verdict.json：找最新的 run 目录
 80→    const runBaseDir = path.join(repoRoot, 'web', 'data', 'prism-out', runId);
 81→    if (!fs.existsSync(runBaseDir)) {
 82→      console.error(`[pipeline] --skip-explore but run dir not found: ${runBaseDir}`);
 83→      process.exit(1);
 84→    }
 85→    // 找含 findings.json 的最新时间戳子目录（过滤掉 base/cur/throttle 等 triad 数据目录）
 86→    const subdirs = fs.readdirSync(runBaseDir)
 87→      .filter(d => fs.statSync(path.join(runBaseDir, d)).isDirectory())
 88→      .filter(d => fs.existsSync(path.join(runBaseDir, d, 'findings.json')))
 89→      .sort()
 90→      .reverse();
 91→    exploreOutputDir = subdirs.length > 0
 92→      ? path.join(runBaseDir, subdirs[0])
 93→      : runBaseDir;
 94→    if (!fs.existsSync(path.join(exploreOutputDir, 'findings.json'))) {
 95→      console.error(`[pipeline] --skip-explore but findings.json not found in: ${exploreOutputDir}`);
 96→      process.exit(1);
 97→    }
 98→    console.log(`[pipeline] Stage 1 (explore): SKIPPED, reusing ${exploreOutputDir}`);
 99→
100→    // WT-031 需求 C：--skip-explore 模式下支持 --out 新目录，不覆盖原报告
101→    if (outputDir) {
102→      // 用户显式指定 --out：narrative + render 写到新目录，原 exploreOutputDir 不动
103→      // 相对于 cwd 解析（用户通常在 web/ 下跑，--out data/prism-out/... → web/data/prism-out/...）
104→      // 这样 narrative-service 和 render-html 都能正确找到 perfetto triad 数据（在 runBase/cur/ 下）
105→      narrativeOutputDir = path.isAbsolute(outputDir)
106→        ? outputDir
107→        : path.resolve(process.cwd(), outputDir);
108→      if (!fs.existsSync(narrativeOutputDir)) {
109→        fs.mkdirSync(narrativeOutputDir, { recursive: true });
110→        console.log(`[pipeline] Created new output dir: ${narrativeOutputDir}`);
111→      }
112→      // 复制 findings.json + verdict.json 到新目录（narrative-service 要读 findings.json）
113→      for (const fname of ['findings.json', 'verdict.json']) {
114→        const src = path.join(exploreOutputDir, fname);
115→        const dst = path.join(narrativeOutputDir, fname);
116→        if (fs.existsSync(src) && !fs.existsSync(dst)) {
117→          fs.copyFileSync(src, dst);
118→          console.log(`[pipeline] Copied ${fname} → ${narrativeOutputDir}`);
119→        }
120→      }
121→      console.log(`[pipeline] --skip-explore + --out: narrative/render will write to ${narrativeOutputDir} (original ${exploreOutputDir} untouched)`);
122→    } else {
123→      // 未给 --out：保持原行为（写到 exploreOutputDir），但打 warning
124→      console.warn(`[pipeline] WARNING: --skip-explore without --out will overwrite existing narrative.json/report.html in ${exploreOutputDir}`);
125→      console.warn(`[pipeline] Suggestion: add --out data/prism-out/${runId}/<new-timestamp> to preserve original`);
126→      narrativeOutputDir = exploreOutputDir;
127→    }
128→  } else {
129→    console.log('[pipeline] Stage 1 (explore): starting...');
130→    const exploreResult = await runPrismExplore({
131→      source: 'perfetto',
132→      runId,
133→      outputDir,
134→      timeoutMs: timeoutMs ?? 20 * 60 * 1000,
135→    });
136→    if (!exploreResult.success) {
137→      console.error(`[pipeline] Stage 1 (explore) FAILED: ${exploreResult.error}`);
138→      process.exit(1);
139→    }
140→    exploreOutputDir = path.dirname(exploreResult.findingsPath);
141→    narrativeOutputDir = outputDir ? path.resolve(repoRoot, outputDir) : exploreOutputDir;
142→    console.log(`[pipeline] Stage 1 (explore): OK, ${exploreResult.findings.length} findings → ${exploreOutputDir}`);
143→  }
144→
145→  // ── 阶段 2：narrative LLM ──
146→  console.log('[pipeline] Stage 2 (narrative): starting...');
147→  const narrativeResult = await runPrismNarrative({
148→    source: 'perfetto',
149→    runId,
150→    outputDir: narrativeOutputDir,
151→    timeoutMs: timeoutMs ?? 10 * 60 * 1000,
152→  });
153→  if (!narrativeResult.success) {
154→    console.error(`[pipeline] Stage 2 (narrative) FAILED: ${narrativeResult.error}`);
155→    process.exit(1);
156→  }
157→  console.log(`[pipeline] Stage 2 (narrative): OK → ${narrativeResult.narrativePath}`);
158→
159→  // ── 阶段 3：render 纯代码 ──
160→  console.log('[pipeline] Stage 3 (render): starting...');
161→  const renderScript = path.join(__dirname, 'render-html.ts');
162→  const renderArgs = ['--import', 'tsx', renderScript, '--dir', narrativeOutputDir];
163→  const renderExitCode = await new Promise<number>((resolve) => {
164→    const child = spawn('node', renderArgs, {
165→      cwd: path.join(repoRoot, 'web'),
166→      stdio: 'inherit',
167→      shell: false,
168→    });
169→    child.on('close', resolve);
170→    child.on('error', (err) => {
171→      console.error(`[pipeline] Stage 3 (render) spawn error: ${err.message}`);
172→      resolve(1);
173→    });
174→  });
175→  if (renderExitCode !== 0) {
176→    console.error(`[pipeline] Stage 3 (render) FAILED: exit code ${renderExitCode}`);
177→    process.exit(1);
178→  }
179→  const reportHtmlPath = path.join(narrativeOutputDir, 'report.html');
180→  console.log(`[pipeline] Stage 3 (render): OK → ${reportHtmlPath}`);
181→
182→  console.log('\n════════════════════════════════════════');
183→  console.log('  Perfetto 三段管线 — 完成');
184→  console.log('════════════════════════════════════════');
185→  console.log(`  findings.json  : ${path.join(narrativeOutputDir, 'findings.json')}`);
186→  console.log(`  narrative.json : ${narrativeResult.narrativePath}`);
187→  console.log(`  report.html    : ${reportHtmlPath}`);
188→  console.log('════════════════════════════════════════');
189→}
190→
191→main().catch((err) => {
192→  console.error('[pipeline] Unexpected error:', err instanceof Error ? err.message : String(err));
193→  process.exit(1);
194→});
