  1→import { FastifyInstance } from 'fastify';
  2→import { eq } from 'drizzle-orm';
  3→import { getDb } from '../db/index.js';
  4→import { sessions } from '../db/schema.js';
  5→import { analysisQueue } from '../services/analysis-queue.js';
  6→import {
  7→  readAnalysisLogs,
  8→  readPreprocessJson,
  9→  readReportMarkdown,
 10→  readReportMetrics,
 11→} from '../services/report-artifacts.js';
 12→import type { ProgressEvent, CliProvider } from '../../shared/types.js';
 13→
 14→// 存储 SSE 连接
 15→const sseClients = new Map<string, Set<(event: ProgressEvent) => void>>();
 16→
 17→/** 发送进度事件到所有监听的客户端 */
 18→export function emitProgress(event: ProgressEvent) {
 19→  const clients = sseClients.get(event.sessionId);
 20→  if (clients) {
 21→    for (const send of clients) {
 22→      send(event);
 23→    }
 24→  }
 25→}
 26→
 27→export async function analysisRoutes(app: FastifyInstance) {
 28→  /**
 29→   * POST /api/analysis/start
 30→   * 触发分析（将任务加入队列）
 31→   */
 32→  app.post('/analysis/start', async (request, reply) => {
 33→    const { sessionId, cliProvider = 'codebuddy', params } = request.body as {
 34→      sessionId: string;
 35→      cliProvider?: CliProvider;
 36→      params?: { targetFps?: number; jankMultiplier?: number; bigJankMultiplier?: number; budgetRatio?: number };
 37→    };
 38→
 39→    if (!sessionId) {
 40→      return reply.status(400).send({ error: '缺少 sessionId' });
 41→    }
 42→
 43→    const db = getDb();
 44→    const session = await db.select().from(sessions).where(eq(sessions.id, sessionId)).get();
 45→
 46→    if (!session) {
 47→      return reply.status(404).send({ error: '分析会话不存在' });
 48→    }
 49→
 50→    if (session.status === 'running' || session.status === 'completed') {
 51→      return reply.status(409).send({ error: `会话状态为 ${session.status}，不能重新触发` });
 52→    }
 53→
 54→    // 加入分析队列（传递 CLI 提供者和分析参数）
 55→    const position = analysisQueue.enqueue(sessionId, cliProvider, params);
 56→
 57→    // 更新状态
 58→    await db.update(sessions).set({ status: 'queued' }).where(eq(sessions.id, sessionId));
 59→
 60→    return reply.send({
 61→      sessionId,
 62→      status: 'queued',
 63→      queuePosition: position,
 64→    });
 65→  });
 66→
 67→  /**
 68→   * GET /api/analysis/:id
 69→   * 获取分析状态和结果
 70→   */
 71→  app.get('/analysis/:id', async (request, reply) => {
 72→    const { id } = request.params as { id: string };
 73→    const db = getDb();
 74→
 75→    const session = await db.select().from(sessions).where(eq(sessions.id, id)).get();
 76→    if (!session) {
 77→      return reply.status(404).send({ error: '不存在' });
 78→    }
 79→
 80→    return reply.send(session);
 81→  });
 82→
 83→  /**
 84→   * GET /api/analysis/:id/progress
 85→   * SSE 端点 - 实时推送分析进度
 86→   */
 87→  app.get('/analysis/:id/progress', async (request, reply) => {
 88→    const { id } = request.params as { id: string };
 89→
 90→    reply.raw.writeHead(200, {
 91→      'Content-Type': 'text/event-stream',
 92→      'Cache-Control': 'no-cache',
 93→      'Connection': 'keep-alive',
 94→      'Access-Control-Allow-Origin': '*',
 95→    });
 96→
 97→    // 注册 SSE 客户端
 98→    if (!sseClients.has(id)) {
 99→      sseClients.set(id, new Set());
100→    }
101→
102→    const send = (event: ProgressEvent) => {
103→      try {
104→        if (!reply.raw.writable) return;
105→        const canContinue = reply.raw.write(
106→          `data: ${JSON.stringify(event)}\n\n`
107→        );
108→        if (!canContinue) {
109→          // 背压处理 - 暂停流(如有引用)
110→          console.warn('[SSE] Backpressure detected for session', event.sessionId);
111→        }
112→      } catch (err: any) {
113→        console.error(`[SSE] Write error for session ${event.sessionId}:`, err.message);
114→      }
115→    };
116→
117→    sseClients.get(id)!.add(send);
118→
119→    // 客户端断开时清理
120→    request.raw.on('close', () => {
121→      const clients = sseClients.get(id);
122→      if (clients) {
123→        clients.delete(send);
124→        if (clients.size === 0) {
125→          sseClients.delete(id);
126→        }
127→      }
128→    });
129→
130→    // 发送初始心跳，并回放当前会话状态，避免任务快速失败/完成时前端错过 SSE 事件
131→    reply.raw.write(`data: ${JSON.stringify({ type: 'connected', sessionId: id })}\n\n`);
132→
133→    try {
134→      const db = getDb();
135→      const session = await db.select().from(sessions).where(eq(sessions.id, id)).get();
136→      if (session?.status === 'failed') {
137→        send({
138→          sessionId: id,
139→          stage: 'failed',
140→          progress: 0,
141→          message: session.error || '分析失败',
142→          timestamp: Date.now(),
143→          log: session.error ? `[错误] ${session.error}` : undefined,
144→        });
145→      } else if (session?.status === 'completed') {
146→        send({
147→          sessionId: id,
148→          stage: 'completed',
149→          progress: 100,
150→          message: '分析完成，报告已保存',
151→          timestamp: Date.now(),
152→        });
153→      } else if (session?.status === 'running') {
154→        send({
155→          sessionId: id,
156→          stage: 'analyzing',
157→          progress: 50,
158→          message: '分析仍在进行中...',
159→          timestamp: Date.now(),
160→        });
161→      }
162→    } catch (err: any) {
163→      console.warn(`[SSE] Failed to replay session status ${id}:`, err.message);
164→    }
165→  });
166→
167→  /**
168→   * GET /api/analysis/queue/status
169→   * 获取队列状态
170→   */
171→  app.get('/analysis/queue/status', async (_request, reply) => {
172→    return reply.send(analysisQueue.getStatus());
173→  });
174→
175→  /**
176→   * GET /api/report/:id/content
177→   * 获取报告 Markdown 内容
178→   */
179→  app.get('/report/:id/content', async (request, reply) => {
180→    const { id } = request.params as { id: string };
181→    const content = readReportMarkdown(id);
182→    if (!content) return reply.status(404).send('');
183→    reply.header('Content-Type', 'text/plain; charset=utf-8');
184→    return reply.send(content);
185→  });
186→
187→  /**
188→   * GET /api/report/:id/metrics
189→   * 获取分析指标 (legacy 表 / preprocess-result.json)
190→   */
191→  app.get('/report/:id/metrics', async (request, reply) => {
192→    const { id } = request.params as { id: string };
193→    const metric = readReportMetrics(id);
194→    if (!metric) return reply.status(404).send({ error: '无指标数据' });
195→    return reply.send(metric);
196→  });
197→
198→  /**
199→   * GET /api/report/:id/logs
200→   * 获取分析日志
201→   */
202→  app.get('/report/:id/logs', async (request, reply) => {
203→    const { id } = request.params as { id: string };
204→    const content = readAnalysisLogs(id);
205→    if (!content) return reply.status(404).send('');
206→    reply.header('Content-Type', 'text/plain; charset=utf-8');
207→    return reply.send(content);
208→  });
209→
210→  /**
211→   * GET /api/report/:id/preprocess
212→   * 获取预处理结构化数据 (preprocess-result.json)
213→   */
214→  app.get('/report/:id/preprocess', async (request, reply) => {
215→    const { id } = request.params as { id: string };
216→    const data = readPreprocessJson(id);
217→    if (!data) return reply.status(404).send({ error: '无预处理数据' });
218→    reply.header('Content-Type', 'application/json; charset=utf-8');
219→    return reply.send(data);
220→  });
221→
222→  /**
223→   * DELETE /api/analysis/:id
224→   * 删除分析记录
225→   */
226→  app.delete('/analysis/:id', async (request, reply) => {
227→    const { id } = request.params as { id: string };
228→    const db = getDb();
229→
230→    await db.delete(sessions).where(eq(sessions.id, id));
231→
232→    return reply.send({ success: true });
233→  });
234→}
