313→const SOURCE_LABELS: Record<string, string> = {
314→  unity_profiler: 'Unity',
315→  simpleperf: 'simpleperf',
316→  perfetto: 'Perfetto',
317→};
318→
319→const SOURCE_COLORS: Record<string, string> = {
320→  unity_profiler: 'green',
