325→/** 根据 Run 的 sources 生成可分析选项 (单源 + 多源组合)。 */
326→function buildAnalysisOptions(sources: string[]): { label: string; sources: string[] }[] {
327→  const opts: { label: string; sources: string[] }[] = [];
328→  // 单源
329→  for (const s of sources) {
330→    opts.push({ label: `${SOURCE_LABELS[s] ?? s} 单源`, sources: [s] });
331→  }
332→  // 全源交叉
333→  if (sources.length >= 2) {
334→    opts.push({
335→      label: sources.length === 2 ? '双源交叉' : sources.length === 3 ? '三源交叉' : `${sources.length} 源交叉`,
336→      sources,
337→    });
338→  }
339→  return opts;
340→}
341→
342→/** 抽屉内的 Run 列表 */
343→function VersionRunDrawer({
344→  items,
345→  loading,
346→  analyzing,
347→  onAnalyze,
348→  onViewRun,
349→}: {
350→  items: VersionRunItem[];
351→  loading: boolean;
352→  analyzing: string | null;
353→  onAnalyze: (runId: string, sources: string[]) => void;
354→  onViewRun: (runId: string) => void;
355→}) {
356→  if (loading) {
357→    return <div style={{ textAlign: 'center', padding: 40 }}><Spin tip="加载 Run 列表..." /></div>;
358→  }
359→  if (items.length === 0) {
360→    return <Empty description="该版本暂无 Run" />;
361→  }
362→
363→  return (
364→    <Space direction="vertical" size={12} style={{ width: '100%' }}>
365→      {items.map(run => {
366→        const analysisOptions = buildAnalysisOptions(run.sources);
367→        const menuItems: MenuProps['items'] = analysisOptions.map(opt => ({
368→          key: opt.sources.join('+'),
369→          label: opt.label,
370→          onClick: () => onAnalyze(run.id, opt.sources),
371→        }));
372→
373→        return (
374→          <Card key={run.id} size="small" bodyStyle={{ padding: 12 }}>
375→            {/* 第一行: 源标签 + 设备/场景 */}
376→            <Space wrap size={[6, 6]}>
377→              {run.sources.map(s => (
378→                <Tag key={s} color={SOURCE_COLORS[s] ?? 'default'} style={{ fontSize: 11 }}>
379→                  {SOURCE_LABELS[s] ?? s}
380→                </Tag>
381→              ))}
382→              <Text style={{ fontSize: 12 }}>{run.device || '—'} / {run.scene || '—'}</Text>
383→            </Space>
384→
385→            {/* 第二行: 时间 + label */}
386→            <div style={{ marginTop: 4 }}>
387→              <Text type="secondary" style={{ fontSize: 11 }}>
388→                {dayjs(run.createdAt).format('MM-DD HH:mm')}
389→                {run.label ? ` · ${run.label}` : ''}
390→              </Text>
391→            </div>
392→
393→            {/* 第三行: 已有分析 */}
394→            {run.analyses.length > 0 && (
395→              <div style={{ marginTop: 8 }}>
396→                <Text type="secondary" style={{ fontSize: 11 }}>已有 AI 分析:</Text>
397→                <Space wrap size={[4, 4]} style={{ marginTop: 4 }}>
398→                  {run.analyses.map(a => (
399→                    <Tag
400→                      key={a.id}
401→                      icon={a.hasReport ? <CheckCircleOutlined /> : undefined}
402→                      color={a.hasReport ? 'success' : 'default'}
403→                      style={{ fontSize: 11, cursor: 'pointer' }}
404→                      onClick={() => onViewRun(run.id)}
405→                    >
406→                      {a.typeLabel}
407→                    </Tag>
408→                  ))}
409→                </Space>
410→              </div>
411→            )}
412→
413→            {/* 第四行: 操作按钮 */}
414→            <div style={{ marginTop: 10, display: 'flex', gap: 8 }}>
415→              <Button
416→                size="small"
417→                icon={<EyeOutlined />}
418→                onClick={() => onViewRun(run.id)}
419→              >
420→                查看详情
421→              </Button>
422→              <Dropdown menu={{ items: menuItems }}>
423→                <Button
424→                  size="small"
425→                  type="primary"
426→                  ghost
427→                  icon={<ThunderboltOutlined />}
428→                  loading={analyzing === run.id}
429→                >
430→                  新建分析 <DownOutlined />
431→                </Button>
432→              </Dropdown>
433→            </div>
434→          </Card>
435→        );
436→      })}
437→    </Space>
438→  );
439→}
