270→function ingestDoneResponse(event: IngestJobEvent): IngestRunResponse | null {
271→  if (event.type !== 'done' || !event.runId) return null;
272→  return {
273→    runId: event.runId,
274→    sources: event.sources ?? [],
275→    label: event.label,
276→    url: `/runs/${event.runId}`,
277→    runIds: event.runIds,
278→    triadId: event.triadId,
279→    diffId: event.diffId,
280→    reportPath: event.reportPath,
281→    reportMarkdown: event.reportMarkdown,
282→  };
283→}
