285→async function pollIngestJob(jobId: string, onEvent?: (event: IngestJobEvent) => void): Promise<IngestRunResponse> {
286→  let seen = 0;
287→  while (true) {
288→    const data = await request<{ job: { status: string; error?: string }; events: IngestJobEvent[] }>(`/runs/ingest/jobs/${jobId}`);
289→    for (const event of data.events.slice(seen)) onEvent?.(event);
290→    seen = data.events.length;
291→    const lastDone = [...data.events].reverse().map(ingestDoneResponse).find(Boolean);
292→    if (lastDone) return lastDone;
293→    if (data.job.status === 'failed') throw new Error(data.job.error || '入库失败');
294→    await new Promise(resolve => setTimeout(resolve, 2000));
295→  }
296→}
297→
298→export function waitIngestJob(
299→  jobId: string,
300→  onEvent?: (event: IngestJobEvent) => void,
301→): Promise<IngestRunResponse> {
302→  return new Promise((resolve, reject) => {
303→    let settled = false;
304→    const fallback = () => {
305→      if (settled) return;
306→      void pollIngestJob(jobId, onEvent).then(resolve, reject).finally(() => { settled = true; });
307→    };
308→    const es = new EventSource(`${BASE_URL}/runs/ingest/jobs/${jobId}/events`);
309→    es.onmessage = (ev) => {
310→      try {
311→        const data = JSON.parse(ev.data) as IngestJobEvent;
312→        if (data.type === 'connected') return;
313→        onEvent?.(data);
314→        const done = ingestDoneResponse(data);
315→        if (done) {
316→          settled = true;
317→          es.close();
318→          resolve(done);
319→        }
320→        if (data.type === 'error') {
321→          settled = true;
322→          es.close();
323→          reject(new Error(data.error || data.message || '入库失败'));
324→        }
325→      } catch {
326→        /* ignore malformed */
327→      }
328→    };
329→    es.onerror = () => {
330→      es.close();
331→      fallback();
332→    };
333→  });
334→}
