336→async function ingestWithProgress(
337→  start: () => Promise<IngestJobStartResponse>,
338→  onEvent?: (event: IngestJobEvent) => void,
339→): Promise<IngestRunResponse> {
340→  const { jobId } = await start();
341→  return waitIngestJob(jobId, onEvent);
342→}
