579→/** 启动 AI 优化建议任务，返回 taskId + sourceFiles，然后用 EventSource 订阅进度 */
580→export function requestOptimizeSuggest(
581→  body: OptimizeSuggestRequest & { issueKey: string },
582→  onEvent: (event: any) => void,
583→  onDone: () => void,
584→  onError: (err: string) => void,
585→): () => void {
586→  let eventSource: EventSource | null = null;
587→  let cancelled = false;
588→  let taskId: string | null = null;
589→
590→  fetch(`${BASE_URL}/optimize/start`, {
591→    method: 'POST',
592→    headers: { 'Content-Type': 'application/json' },
593→    body: JSON.stringify(body),
594→  }).then(async (res) => {
595→    if (cancelled) return;
596→    if (!res.ok) {
597→      const err = await res.json().catch(() => ({ error: res.statusText }));
598→      onError(err.error || `请求失败: ${res.status}`);
599→      return;
600→    }
601→
602→    const data = await res.json();
603→    taskId = data.taskId;
604→
605→    if (data.sourceFiles?.length) {
606→      onEvent({ type: 'source_found', sourceFiles: data.sourceFiles });
607→    }
608→
609→    if (cancelled) return;
610→
611→    eventSource = new EventSource(`${BASE_URL}/optimize/progress/${taskId}`);
612→
613→    eventSource.onmessage = (msg) => {
614→      try {
615→        const event = JSON.parse(msg.data);
616→        if (event.type === 'connected') return;
617→        onEvent(event);
618→        if (event.type === 'done' || event.type === 'error') {
619→          eventSource?.close();
620→          onDone();
621→        }
622→      } catch { /* skip */ }
623→    };
624→
625→    eventSource.onerror = () => {
626→      eventSource?.close();
627→      if (!cancelled) {
628→        onDone();
629→      }
630→    };
631→  }).catch((err) => {
632→    if (!cancelled) {
633→      onError(err.message);
634→    }
635→  });
636→
637→  return () => {
638→    cancelled = true;
639→    eventSource?.close();
640→    if (taskId) {
641→      fetch(`${BASE_URL}/optimize/cancel/${taskId}`, { method: 'POST' }).catch(() => {});
642→    }
643→  };
644→}
